SELECT COUNT(*)
FROM aftersales a
WHERE a.company_id = #{companyId}
AND a.distributor_id = #{distributorId}
AND a.create_time >= #{start}
AND a.create_time <= #{end}

SELECT IFNULL(SUM(r.refunded_fee), 0)
FROM aftersales_refund r
WHERE r.company_id = #{companyId}
AND r.distributor_id = #{distributorId}
AND r.update_time >= #{start}
AND r.update_time <= #{end}
AND r.refund_status = 'SUCCESS'

SELECT IFNULL(SUM(CAST(t.total_fee AS SIGNED)), 0)
FROM trade t
WHERE t.company_id = #{companyId}
AND t.distributor_id = #{distributorId}
AND t.trade_state IN ('REFUND_PROCESS', 'REFUND_SUCCESS', 'SUCCESS')
AND t.time_expire >= #{start}
AND t.time_expire <= #{end}

